const dx = global.get('dx');
msg.topic = dx.storage.schema.createSpotsTable();
return msg;

// sqlite 节点只有 1 个输出，建表完成后由这里扇出到两条独立支路。
// Node-RED 中 [a,b,c] 是往第 1 个输出发 3 条；要发到多个输出必须返回嵌套数组。
// 邻台建表由单独的 inject 触发，避免与列迁移并发重复 DROP/CREATE 触发器。
const clone = () => Object.assign({}, msg);
return [[clone()], [clone()]];

const dx = global.get('dx');
msg.topic = dx.storage.schema.checkSpotIdColumn();
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.schema.migrateLegacyDb(msg.payload);
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.schema.uniqueSpotIndex();
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.schema.checkExtraColumns();
return msg;

const dx = global.get('dx');
const cols = dx.storage.schema.columnNames(msg.payload);
const topics = dx.storage.schema.addMissingColumns(msg.payload);
if (!cols.length) {
    // 读不到列名时绝不盲发 ALTER，避免把已有列再 ADD 一次。
    node.warn('DB migration: spots column list unavailable, ALTER skipped');
    return null;
}
if (!topics.length) {
    node.log('DB migration: spots columns already complete [' + cols.join(', ') + ']');
    return null;
}
node.log('DB migration: adding ' + topics.length + ' column(s), existing [' + cols.join(', ') + ']');
// 每条 ALTER 独立发送，单条失败（duplicate column name）不影响其余列。
return [topics.map(topic => ({topic: topic}))];

const dx = global.get('dx');
const request = dx.spots.liveRequest({global, flow});
if (!request) return null;
Object.assign(msg, request);
return msg;

const dx = global.get('dx');
Object.assign(msg, dx.spots.backfillRequest(msg.payload && msg.payload.call));
return msg;

const dx = global.get('dx');
const result = dx.spots.ingest('dxwatch', msg.payload, {global, flow, backfillCall: msg.backfillCall});
if (result.warning) node.warn(result.warning);
if (!result.records.length) return null;
return [result.records.map(payload => ({payload})), result.fresh.length ? result.fresh.map(payload => ({payload})) : null];

const dx = global.get('dx');
msg.topic = dx.storage.spots.insert(msg.payload);
return msg;

// The enriched spot object in msg.payload is JSON-encoded by the websocket out node.
// 条件告警只对 fresh spot 评估，历史回填不触发。
msg.alertSpot = msg.payload;
return msg;

const dx = global.get('dx');
msg.headers = {'Content-Type': 'application/json'};
msg.payload = dx.settings.getCallsigns(global);
return msg;

const dx = global.get('dx');
const result = dx.settings.saveCallsigns(global, msg.payload);
msg.headers = {'Content-Type': 'application/json'};
msg.payload = result.payload;
return [msg, result.fresh.map(call => ({payload: {call}}))];

const dx = global.get('dx');
msg.topic = dx.storage.spots.query(msg.req.query.call, msg.req.query.limit);
msg.headers = {'Content-Type': 'application/json'};
return msg;

msg.headers = {'Content-Type': 'application/json'};
msg.payload = {};
return msg;

msg.headers = {'Content-Type': 'application/json'};
msg.payload = {success: true};
return msg;

const dx = global.get('dx');
Object.assign(msg, dx.spots.mainPageRequest());
return msg;

const dx = global.get('dx');
const hash = dx.spots.extractRbnHash(msg.payload);
if (hash) {
    flow.set('rbnH', hash);
    node.status({fill: 'green', shape: 'dot', text: 'h=' + hash});
} else {
    node.status({fill: 'red', shape: 'ring', text: 'hash not found'});
}
return null;

const dx = global.get('dx');
const request = dx.spots.rbnRequest({global, flow});
if (!request) return null;
Object.assign(msg, request);
return msg;

const dx = global.get('dx');
const result = dx.spots.ingest('rbn', msg.payload, {global, flow, statusCode: msg.statusCode});
if (result.warning) node.warn(result.warning);
if (result.refreshHash) return [null, null, {payload: ''}];
if (!result.records.length) return null;
return [result.records.map(payload => ({payload})), result.fresh.length ? result.fresh.map(payload => ({payload})) : null, null];

const dx = global.get('dx');
const result = dx.spots.ingest('pskr', msg.payload, {global, flow});
if (!result.records.length) return [null, null];
return [{payload: result.records[0]}, result.fresh.length ? {payload: result.fresh[0]} : null];

const dx = global.get('dx');
const result = dx.spots.syncPskrSubscriptions({global, flow});
for (const action of result.actions) node.send(action);
if (result.warning) node.warn(result.warning);
return null;

const dx = global.get('dx');
msg.topic = dx.storage.schema.createRecordingTable();
return msg;

const dx = global.get('dx');
const row = dx.recording.prepareSpot(msg.payload, global.get('recording'));
if (!row) return null;
msg.topic = dx.storage.recording.insert(row);
return msg;

const dx = global.get('dx');
const result = dx.recording.tick(global, new Date());
for (const warning of result.warnings) node.warn(warning);
return null;

const dx = global.get('dx');
try {
    const result = dx.maintenance.purge(global);
    const statements = (result && result.statements) || [];
    if (!statements.length) {
        node.status({fill: 'grey', shape: 'dot', text: 'auto purge off'});
        return null;
    }
    node.status({fill: 'green', shape: 'dot', text: 'purge ' + statements.map(s => s.scope).join(',')});
    node.warn('retention purge: ' + statements.map(s => s.scope).join(', '));
    return [statements.map(s => ({topic: s.topic, payload: s.scope}))];
} catch (e) {
    node.status({fill: 'red', shape: 'ring', text: e.message});
    node.warn('retention purge failed: ' + e.message);
    return null;
}

const dx = global.get('dx');
try {
    const r = dx.maintenance.diskCheck(global);
    if (r && r.error) {
        node.status({fill: 'red', shape: 'ring', text: 'disk: ' + r.error});
        node.warn('disk check failed: ' + r.error);
    } else if (r && r.enabled === false) {
        node.status({fill: 'grey', shape: 'dot', text: 'disk alert off'});
    } else if (r && !r.skipped) {
        const text = 'disk ' + r.usedPct + '% used, ' + r.freeGb + ' GB free';
        node.status({fill: r.warn ? 'yellow' : 'green', shape: 'dot', text});
        if (r.transition === 'raised') node.warn('LOW DISK: ' + text + ' (threshold ' + r.threshold + '%)');
        if (r.transition === 'cleared') node.warn('disk space OK again: ' + text);
    }
} catch (e) {
    node.status({fill: 'red', shape: 'ring', text: e.message});
    node.warn('disk check failed: ' + e.message);
}
return null;

const dx = global.get('dx');
msg.headers = {'Content-Type': 'application/json'};
msg.payload = dx.recording.status(global);
return msg;

const dx = global.get('dx');
const result = dx.recording.control(global, msg.payload, new Date());
if (result.statusCode) msg.statusCode = result.statusCode;
msg.headers = {'Content-Type': 'application/json'};
msg.payload = result.payload;
return msg;

const dx = global.get('dx');
msg.headers = {'Content-Type': 'application/json'};
msg.payload = dx.monitoring.setClient(global, msg.payload, Date.now());
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.recording.query(msg.req.query.call, msg.req.query.limit);
msg.headers = {'Content-Type': 'application/json'};
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.spots.clear();
msg.payload = {ok: true};
msg.headers = {'Content-Type': 'application/json'};
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.schema.createQsosTable();
return msg;

const dx = global.get('dx');
const radio = dx.qso.saveRadio(global, msg.payload, new Date());
if (!radio) return null;
msg.payload = radio;
return msg;

const dx = global.get('dx');
const route = dx.qso.routeContact(msg.payload);
if (route === 'contactinfo') return [msg, null, null];
if (route === 'contactreplace') return [null, msg, null];
if (route === 'contactdelete') return [null, null, msg];
return null;

const dx = global.get('dx');
const qso = dx.qso.parseContact(msg.payload, new Date());
if (!qso) return null;
msg.qso = qso;
msg.topic = dx.storage.qso.upsert(qso);
return msg;

const dx = global.get('dx');
const route = dx.qso.coordinateRoute(msg.qso, !!flow.get('qrzkey'));
if (!route) return null;
if (route === 'qrz') return [msg, null, null];
if (route === 'broadcast') {
    msg.payload = msg.qso;
    return [null, null, msg];
}
msg.topic = dx.qso.coordinateTopic(msg.qso);
return [null, msg, null];

const dx = global.get('dx');
if (!msg.qso) return null;
msg.payload = dx.qso.applySpotCoords(msg.qso, msg.payload);
return msg;

const dx = global.get('dx');
const removed = dx.qso.parseDelete(msg.payload);
if (!removed) return null;
msg.qso = removed.qso;
msg.topic = dx.storage.qso.remove(removed.id, removed.call, removed.timestamp);
return msg;

const dx = global.get('dx');
const score = dx.qso.saveScore(global, msg.payload, new Date());
if (!score) return null;
msg.payload = score;
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.qso.query(msg.req.query.limit);
msg.headers = {'Content-Type': 'application/json'};
return msg;

const dx = global.get('dx');
msg.payload = dx.qso.stationState(global);
msg.headers = {'Content-Type': 'application/json'};
return msg;

const dx = global.get('dx');
const request = dx.qso.callsignQuery(msg.qso, flow.get('qrzkey'));
if (!request) return null;
Object.assign(msg, request);
return msg;

const dx = global.get('dx');
const result = dx.qso.parseResult(msg.payload, msg.qso);
if (!result) return null;
if (result.kind === 'coords') {
    msg.topic = result.topic;
    msg.payload = result.qso;
    return [msg, null, null];
}
if (result.kind === 'sessionError') {
    flow.set('qrzkey', null);
    node.status({fill: 'red', shape: 'ring', text: result.error});
    return [null, msg, msg];
}
return [null, msg, null];

const dx = global.get('dx');
if (!msg.qso) return null;
if (msg.qso.lat !== null && msg.qso.lat !== undefined) {
    msg.payload = msg.qso;
    return [null, msg];
}
msg.topic = dx.qso.coordinateTopic(msg.qso);
return [msg, null];

const dx = global.get('dx');
const result = dx.settings.saveQrz(flow, msg.payload);
if (result.statusCode) msg.statusCode = result.statusCode;
else msg.headers = {'Content-Type': 'application/json'};
msg.payload = result.payload;
return [msg, result.login ? {} : null];

const dx = global.get('dx');
const request = dx.qso.login(flow.get('qrzuser'), flow.get('qrzpass'));
if (!request) return null;
Object.assign(msg, request);
return msg;

const dx = global.get('dx');
const result = dx.qso.parseKey(msg.payload);
if (result.key) {
    flow.set('qrzkey', result.key);
    flow.set('qrzkeyexpire', result.expire);
    node.status({fill: 'green', shape: 'dot', text: 'QRZ session ok'});
    return null;
}
if (result.error) node.status({fill: 'red', shape: 'ring', text: result.error});
flow.set('qrzkey', null);
return null;

const dx = global.get('dx');
msg.payload = dx.settings.qrzState(flow);
msg.headers = {'Content-Type': 'application/json'};
return msg;

const dx = global.get('dx');
dx.settings.reset(global, flow);
msg.topic = dx.storage.spots.clear();
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.qso.clear();
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.recording.clear();
return msg;

msg.payload = { ok: true };
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const dx = global.get('dx');
msg.payload = dx.settings.get(global);
return msg;

const dx = global.get('dx');
const result = dx.settings.save(global, msg.payload);
if (result.warnings && result.warnings.length) node.warn('settings fallback: ' + result.warnings.join(' | '));
if (result.statusCode) msg.statusCode = result.statusCode;
msg.payload = result.payload;
return [msg, result.broadcast ? {payload: result.broadcast} : null];

const dx = global.get('dx');
const body = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const result = dx.settings.resetDomain(global, body.domain, body);
if (result.statusCode) msg.statusCode = result.statusCode;
msg.payload = result.payload;
return [msg, result.broadcast ? {payload: result.broadcast} : null];

try {
    const dx = await global.get('dx');
    if (!dx || !dx.propagation || !dx.propagation.collect) {
        throw new Error('dx.propagation module missing from functionGlobalContext');
    }
    const data = await dx.propagation.collect(global);
    const errs = (data && data.errors) || [];
    node.status({fill: errs.length ? 'yellow' : 'green', shape: 'dot',
        text: 'ok ' + new Date().toISOString().slice(11, 16) +
        (errs.length ? ' (' + errs.length + ' err)' : '')});
} catch (e) {
    node.status({fill: 'red', shape: 'ring', text: e.message});
    node.warn('prop collect failed: ' + e.message);
}
return null;

try {
    const dx = await global.get('dx');
    const data = await dx.propagation.getSnapshot(global);
    msg.headers = {'Cache-Control': 'no-store'};
    msg.payload = data || {error: 'collecting'};
} catch (e) {
    msg.statusCode = 500;
    msg.payload = {error: e.message};
}
return msg;

const dx = global.get('dx');
const prepared = dx.analysis.service.prepare(msg.req.query);
msg.topic = prepared.sql;
msg.analysisError = prepared.error;
msg.analysisRequest = prepared.request;
return msg;

const dx = global.get('dx');
const prepared = {
    ok: !msg.analysisError,
    error: msg.analysisError || null,
    request: msg.analysisRequest
};
const result = dx.analysis.service.complete(prepared, msg.payload);
delete msg.analysisRequest;
msg.headers = {'Content-Type': 'application/json'};
msg.statusCode = result.error ? 400 : 200;
msg.payload = result;
return msg;

const dx = global.get('dx');
const prepared = dx.analysis.pathService.prepare(msg.req.query, global);
msg.topic = prepared.neighborSql;
msg.pathError = prepared.error;
msg.pathRequest = prepared.request;
msg.pathSql = prepared.sql;
return msg;

const dx = global.get('dx');
const prepared = {
    ok: !msg.pathError,
    error: msg.pathError || null,
    request: msg.pathRequest,
    sql: msg.pathSql
};
const spots = dx.analysis.pathService.prepareSpots(prepared, msg.payload);
msg.topic = spots.sql;
msg.pathRequest = spots.request;
delete msg.pathSql;
return msg;

const dx = global.get('dx');
const prepared = {
    ok: !msg.pathError,
    error: msg.pathError || null,
    request: msg.pathRequest
};
const result = dx.analysis.pathService.complete(prepared, msg.payload);
delete msg.pathRequest;
msg.headers = {'Content-Type': 'application/json'};
msg.statusCode = result.error ? 400 : 200;
msg.payload = result;
return msg;

const dx = global.get('dx');
const prepared = dx.multipliers.service.prepare(msg.req.query, dx.settings.runtime(global));
msg.topic = prepared.sql;
msg.multiplierError = prepared.error;
msg.multiplierRequest = prepared.request;
return msg;

const dx = global.get('dx');
const prepared = {
    ok: !msg.multiplierError,
    error: msg.multiplierError || null,
    request: msg.multiplierRequest
};
const rows = msg.payload;
delete msg.multiplierRequest;
const result = await dx.multipliers.service.complete(prepared, rows);
msg.headers = {'Content-Type': 'application/json'};
msg.statusCode = result.error ? 400 : 200;
msg.payload = result;
return msg;

const err = msg.error || {};
const detail = String(err.message || err);
node.warn('multiplier request failed: ' + detail);
msg.statusCode = 500;
msg.headers = Object.assign({}, msg.headers, {'content-type': 'application/json; charset=utf-8'});
msg.payload = {ok: false, error: 'query-failed', detail: detail};
return msg;

const dx = global.get('dx');
const err = msg.error || {};
const detail = String(err.message || err);
if (dx.storage.schema.isDuplicateColumnError(detail)) {
    // 列已存在说明目标状态已达成，重复执行不算失败。
    node.log('DB migration skipped: ' + detail + ' (column already present)');
} else {
    node.warn('DB migration failed: ' + detail);
}
return null;

const err = msg.error || {};
const detail = String(err.message || err);
node.warn('analysis request failed: ' + detail);
msg.statusCode = 500;
msg.headers = Object.assign({}, msg.headers, {'content-type': 'application/json; charset=utf-8'});
msg.payload = {ok: false, error: 'query-failed', detail: detail};
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.schema.selfCheckQuery();
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const pick = kind => rows.filter(row => String(row.kind) === kind).map(row => String(row.value));
const spotCols = pick('column');
const tables = pick('table');
const triggers = pick('trigger');
const wantedCols = ['sender_grid', 'receiver_grid', 'dxcc_sender', 'dxcc_receiver'];
const checks = wantedCols.map(name => 'spots.' + name + ' ' + (spotCols.includes(name) ? 'ok' : 'MISSING'));
checks.push('table.neighbors ' + (tables.includes('neighbors') ? 'ok' : 'MISSING'));
for (const name of ['trg_spots_neighbor_tx', 'trg_spots_neighbor_rx']) {
    checks.push(name + ' ' + (triggers.includes(name) ? 'ok' : 'MISSING'));
}
const missing = checks.filter(item => item.endsWith('MISSING'));
node.log('DB self-check: actual spots columns [' + spotCols.join(', ') + ']');
if (missing.length) {
    node.warn('DB self-check: ' + checks.join(', '));
} else {
    node.log('DB self-check ok: ' + checks.join(', '));
}
return null;

const dx = global.get('dx');
msg.topic = dx.storage.alerts.createTable();
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.alerts.list();
return msg;

const dx = global.get('dx');
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const rules = rows.map(dx.alerts.service.fromRow).filter(Boolean);
flow.set('alertRules', rules);
node.status({fill: 'green', shape: 'dot', text: rules.length + ' rules'});
return null;

const dx = global.get('dx');
msg.alertConfig = dx.settings.runtime(global);
msg.topic = dx.storage.alerts.qsoSnapshot(20000);
return msg;

const dx = global.get('dx');
const cfg = msg.alertConfig || dx.settings.runtime(global);
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const window = dx.alerts.service.windowFor(rows, cfg);
const resolve = await dx.alerts.service.resolver();
const index = dx.alerts.rank.buildIndex(rows, resolve, window.from, window.to);
flow.set('alertWorkedIndex', index);
flow.set('alertWindow', window);
node.status({fill: 'green', shape: 'dot', text: index.windowDxcc.size + ' DXCC in window'});
return null;

const dx = global.get('dx');
const spot = msg.alertSpot;
if (!spot) return null;
const cfg = dx.settings.runtime(global);
if (!cfg.alertsEnabled) return null;
const rules = flow.get('alertRules') || [];
if (!rules.length) return null;
const index = flow.get('alertWorkedIndex');
if (!index) return null;
const resolve = await dx.alerts.service.resolver();
const now = Math.floor(Date.now() / 1000);
const outcome = dx.alerts.service.evaluate(spot, {
    settings: cfg,
    rules: rules,
    index: flow.get('alertWorkedIndex') || null,
    resolve: resolve,
    state: {
        now: now,
        dedupe: flow.get('alertDedupe') || {},
        lastAlertAt: flow.get('alertLastAt') || 0
    }
});
flow.set('alertDedupe', outcome.dedupe);
flow.set('alertLastAt', outcome.lastAlertAt);
if (!outcome.alert) return null;
flow.set('alertHits', [outcome.alert].concat(flow.get('alertHits') || []).slice(0, 49));
node.status({fill: 'green', shape: 'dot', text: outcome.alert.call + ' ' + outcome.alert.state});
return {payload: outcome.alert};

const dx = global.get('dx');
msg.topic = dx.storage.alerts.list();
return msg;

const dx = global.get('dx');
const rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.statusCode = 200;
msg.headers = {'content-type': 'application/json; charset=utf-8'};
msg.payload = {ok: true, rules: rows.map(dx.alerts.service.fromRow).filter(Boolean)};
return msg;

const dx = global.get('dx');
const method = String((msg.req && msg.req.method) || 'POST').toUpperCase();
const body = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const input = Object.assign({}, body);
if (msg.req && msg.req.params && msg.req.params.id) input.id = msg.req.params.id;
const result = dx.alerts.service.normalizeRule(input);
if (!result.ok) {
    msg.statusCode = 400;
    msg.headers = {'content-type': 'application/json; charset=utf-8'};
    msg.payload = {ok: false, error: result.error};
    return [null, msg];
}
const sql = method === 'PUT' ? dx.storage.alerts.update(result.rule) : dx.storage.alerts.insert(result.rule);
if (!sql) {
    msg.statusCode = 400;
    msg.headers = {'content-type': 'application/json; charset=utf-8'};
    msg.payload = {ok: false, error: 'invalid-rule'};
    return [null, msg];
}
msg.topic = sql;
msg.alertRule = result.rule;
msg.alertMethod = method;
return [msg, null];

msg.statusCode = 200;
msg.headers = {'content-type': 'application/json; charset=utf-8'};
msg.payload = {ok: true, rule: msg.alertRule};
return msg;

const dx = global.get('dx');
msg.topic = dx.storage.alerts.list();
return msg;

const dx = global.get('dx');
const id = msg.req && msg.req.params ? msg.req.params.id : null;
const sql = dx.storage.alerts.remove(id);
if (!sql) {
    msg.statusCode = 400;
    msg.headers = {'content-type': 'application/json; charset=utf-8'};
    msg.payload = {ok: false, error: 'id-required'};
    return [null, msg];
}
msg.topic = sql;
msg.alertId = Number(id);
return [msg, null];

msg.statusCode = 200;
msg.headers = {'content-type': 'application/json; charset=utf-8'};
msg.payload = {ok: true, id: msg.alertId};
return msg;

const dx = global.get('dx');
const cfg = dx.settings.runtime(global);
const now = Math.floor(Date.now() / 1000);
const ttl = Math.max(60, (Number(cfg.alertDedupeMin) || 10) * 60);
const hits = dx.alerts.rank.aggregate(flow.get('alertHits') || [], ttl, now);
msg.statusCode = 200;
msg.headers = {'content-type': 'application/json; charset=utf-8'};
msg.payload = {ok: true, hits: hits};
return msg;

const err = msg.error || {};
const detail = String(err.message || err);
node.warn('alert pipeline failed: ' + detail);
if (!msg.res) return null;
msg.statusCode = 500;
msg.headers = Object.assign({}, msg.headers, {'content-type': 'application/json; charset=utf-8'});
msg.payload = {ok: false, error: 'alert-failed', detail: detail};
return msg;
